<?php require dirname(__DIR__).'/bootstrap.php';use App\Support\Database;$rows=[];try{$rows=Database::connection()->query("SELECT f.provider_id,f.kickoff,c.name competition_name,h.name home_name,h.logo home_logo,a.name away_name,a.logo away_logo FROM fixtures f JOIN competitions c ON c.id=f.competition_id JOIN teams h ON h.id=f.home_team_id JOIN teams a ON a.id=f.away_team_id WHERE c.prediction_enabled=1 AND f.kickoff>=UTC_TIMESTAMP() ORDER BY f.kickoff LIMIT 20")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$activePage='predictions';?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Predictions — TukiScore</title><link rel="stylesheet" href="assets/app.css"></head><body><?php require __DIR__.'/partials/header.php';?><div class="shell"><div style="max-width:1050px;margin:18px auto 40px"><section class="card"><div class="panel-head"><div><div class="section-label">TUKISCORE FORECASTS</div><h1 style="margin-top:4px">Predictions</h1><div class="subtext">Upcoming matches queued for model analysis.</div></div><div class="segmented"><button class="active">All</button><button>High confidence</button><button>Today</button></div></div><?php if(!$rows):?><div class="empty">No upcoming fixtures are currently available.</div><?php else:?><?php foreach($rows as $r):?><a class="match-row" href="match.php?id=<?=urlencode($r['provider_id'])?>"><div class="match-time"><?=e(substr($r['kickoff'],11,5))?><div class="match-date"><?=e($r['competition_name'])?></div></div><div><div class="team-line"><?=e($r['home_name'])?></div><div class="team-line"><?=e($r['away_name'])?></div></div><div class="score">—</div><span class="badge">MODEL QUEUED</span></a><?php endforeach;?><?php endif;?></section></div><footer class="footer"><span>© <?=date('Y')?> TukiScore</span><span>Probabilities are estimates, not guarantees.</span></footer></div></body></html>